CREATE OR REPLACE VIEW VW_LISTAPRATICHE (
  CODICECOMUNE,
  IDCOMUNE,
  SOFTWARE,
  DESCSOFTWARE,
  IDPRATICA,
  NUMEROPRATICA,
  DATAPRESENTAZIONE,
  ANNOPRESENTAZIONE,
  MESEPRESENTAZIONE,
  NUMEROPROTOCOLLO,
  DATAPROTOCOLLO,
  CODICEINTERVENTO,
  DESCRIZIONEINTERVENTO,
  CODICEPROCEDURA,
  PROCEDURA,
  OGGETTO,
  OGGETTOU,
  CODSTATOPRATICA,
  STATOPRATICA,
  RESPONSABILE,
  RESPONSABILE_TELEFONO,
  PR_CODVIARIO,
  PR_INDIRIZZO,
  PR_CODCIVICO,
  PR_CIVICO,
  CODICEZONIZZAZIONE,
  ZONIZZAZIONE,
  CODICERICHIEDENTE,
  CODICEFISCALE,
  PARTITAIVA,
  NOMINATIVO,
  INDIRIZZO,
  CAP,
  LOCALITA,
  CITTA,
  PROVINCIA,
  TIPORAPPORTO,
  TIPOCATASTO,
  FOGLIO,
  PARTICELLA,
  SUB,
  TEC_CODICE,
  TEC_NOMINATIVO,
  TEC_CODICEFISCALE,
  TEC_PARTITAIVA,
  AZ_CODICE,
  AZ_NOMINATIVO,
  AZ_CODICEFISCALE,
  AZ_PARTITAIVA,
  ISTRUTTORE,
  ISTRUTTORE_TELEFONO,
  OPERATORE,
  OPERATORE_TELEFONO
) AS
SELECT 
  ISTANZE.CODICECOMUNE,
  ISTANZE.IDCOMUNE, ISTANZE.SOFTWARE AS SOFTWARE,SOFTWARE.DESCRIZIONELUNGA AS DESCSOFTWARE,ISTANZE.CODICEISTANZA AS IDPRATICA,ISTANZE.NUMEROISTANZA AS NUMEROPRATICA, TO_CHAR(ISTANZE.DATA,'DD/MM/YYYY') AS DATAPRESENTAZIONE, TO_CHAR(ISTANZE.DATA,'YYYY') AS ANNOPRESENTAZIONE, TO_CHAR(ISTANZE.DATA,'MM') AS MESEPRESENTAZIONE, ISTANZE.NUMEROPROTOCOLLO, TO_CHAR(ISTANZE.DATAPROTOCOLLO,'DD/MM/YYYY') AS DATAPROTOCOLLO, ISTANZE.CODICEINTERVENTOPROC AS CODICEINTERVENTO, VW_ALBEROPROC.SC_DESCRIZIONE AS DESCRIZIONEINTERVENTO, TIPIPROCEDURE.CODICEPROCEDURA, TIPIPROCEDURE.PROCEDURA, ISTANZE.LAVORI AS OGGETTO, UPPER(ISTANZE.LAVORI) AS OGGETTOU, ISTANZE.CHIUSURA AS CODSTATOPRATICA, STATO AS STATOPRATICA, RESPONSABILI.RESPONSABILE, RESPONSABILI.TELEFONOLAVORO AS RESPONSABILE_TELEFONO, NVL(STRADARIO.CODVIARIO,STRADARIO.CODICESTRADARIO) AS PR_CODVIARIO, STRADARIO.PREFISSO || ' ' || STRADARIO.DESCRIZIONE AS PR_INDIRIZZO, ISTANZESTRADARIO.CODICECIVICO AS PR_CODCIVICO, ISTANZESTRADARIO.CIVICO AS PR_CIVICO, ISTANZE.CODICEAREA AS CODICEZONIZZAZIONE, AREE.DENOMINAZIONE AS ZONIZZAZIONE, ANAGRAFE.CODICEANAGRAFE AS CODICERICHIEDENTE, NVL(UPPER(ANAGRAFE.CODICEFISCALE), '') AS CODICEFISCALE, NVL(ANAGRAFE.PARTITAIVA, '') AS PARTITAIVA, ANAGRAFE.NOMINATIVO || ' ' || ANAGRAFE.NOME AS NOMINATIVO, ANAGRAFE.INDIRIZZO, ANAGRAFE.CAP, ANAGRAFE.CITTA AS LOCALITA, COMUNERESIDENZA.COMUNE AS CITTA, COMUNERESIDENZA.PROVINCIA, TIPISOGGETTO.TIPOSOGGETTO AS TIPORAPPORTO, CATASTO.DESCRIZIONE AS TIPOCATASTO, ISTANZEMAPPALI.FOGLIO, ISTANZEMAPPALI.PARTICELLA, ISTANZEMAPPALI.SUB, TECNICO.CODICEANAGRAFE AS TEC_CODICE, TECNICO.NOMINATIVO || ' ' || TECNICO.NOME AS TEC_NOMINATIVO, NVL(UPPER(TECNICO.CODICEFISCALE), '') AS TEC_CODICEFISCALE, NVL(TECNICO.PARTITAIVA, '') AS TEC_PARTITAIVA, AZIENDA.CODICEANAGRAFE AS AZ_CODICE , AZIENDA.NOMINATIVO || ' ' || AZIENDA.NOME AS AZ_NOMINATIVO, NVL(UPPER(AZIENDA.CODICEFISCALE), '') AS AZ_CODICEFISCALE, NVL(AZIENDA.PARTITAIVA, '') AS AZ_PARTITAIVA, ISTRUTTORI.RESPONSABILE AS ISTRUTTORE, ISTRUTTORI.TELEFONOLAVORO AS ISTRUTTORE_TELEFONO, OPERATORI.RESPONSABILE AS OPERATORE, OPERATORI.TELEFONOLAVORO AS OPERATORE_TELEFONO FROM ISTANZE JOIN SOFTWARE ON SOFTWARE.CODICE = ISTANZE.SOFTWARE JOIN ANAGRAFE ON ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE JOIN STATIISTANZA ON STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE AND STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE AND STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA JOIN VW_ALBEROPROC ON VW_ALBEROPROC.IDCOMUNE = ISTANZE.IDCOMUNE AND VW_ALBEROPROC.SC_ID = ISTANZE.CODICEINTERVENTOPROC LEFT OUTER JOIN ANAGRAFE TECNICO ON TECNICO.IDCOMUNE = ISTANZE.IDCOMUNE AND TECNICO.CODICEANAGRAFE = ISTANZE.CODICEPROFESSIONISTA LEFT OUTER JOIN ANAGRAFE AZIENDA ON ISTANZE.IDCOMUNE = AZIENDA.IDCOMUNE AND ISTANZE.CODICETITOLARELEGALE = AZIENDA.CODICEANAGRAFE LEFT OUTER JOIN ISTANZESTRADARIO ON ISTANZE.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND ISTANZE.CODICEISTANZA = ISTANZESTRADARIO.CODICEISTANZA AND 1 = ISTANZESTRADARIO.PRIMARIO LEFT OUTER JOIN STRADARIO ON STRADARIO.IDCOMUNE = ISTANZESTRADARIO.IDCOMUNE AND STRADARIO.CODICESTRADARIO = ISTANZESTRADARIO.CODICESTRADARIO LEFT OUTER JOIN ISTANZEMAPPALI ON ISTANZE.IDCOMUNE = ISTANZEMAPPALI.IDCOMUNE AND ISTANZE.CODICEISTANZA = ISTANZEMAPPALI.FKCODICEISTANZA AND 1 = ISTANZEMAPPALI.PRIMARIO LEFT OUTER JOIN RESPONSABILI ON ISTANZE.IDCOMUNE = RESPONSABILI.IDCOMUNE AND ISTANZE.CODICERESPONSABILEPROC = RESPONSABILI.CODICERESPONSABILE LEFT OUTER JOIN COMUNI COMUNERESIDENZA ON ANAGRAFE.COMUNERESIDENZA = COMUNERESIDENZA.CODICECOMUNE LEFT OUTER JOIN TIPISOGGETTO ON ISTANZE.IDCOMUNE = TIPISOGGETTO.IDCOMUNE AND ISTANZE.FKCODICESOGGETTO = TIPISOGGETTO.CODICETIPOSOGGETTO LEFT OUTER JOIN AREE ON ISTANZE.IDCOMUNE = AREE.IDCOMUNE AND ISTANZE.CODICEAREA = AREE.CODICEAREA LEFT OUTER JOIN CATASTO ON ISTANZEMAPPALI.CODICECATASTO = CATASTO.CODICE LEFT OUTER JOIN TIPIPROCEDURE ON ISTANZE.IDCOMUNE = TIPIPROCEDURE.IDCOMUNE AND ISTANZE.CODICEPROCEDURA = TIPIPROCEDURE.CODICEPROCEDURA LEFT OUTER JOIN RESPONSABILI ISTRUTTORI ON ISTANZE.IDCOMUNE = ISTRUTTORI.IDCOMUNE AND ISTANZE.CODICEISTRUTTORE = ISTRUTTORI.CODICERESPONSABILE LEFT OUTER JOIN RESPONSABILI OPERATORI ON OPERATORI.IDCOMUNE = ISTANZE.IDCOMUNE AND OPERATORI.CODICERESPONSABILE = ISTANZE.CODICERESPONSABILE;

