ALTER TABLE CONFIGURAZIONE ADD CODICEAMMINISTRAZIONE_IPA VARCHAR2(20);
ALTER TABLE CONFIGURAZIONE ADD CODICE_AOO VARCHAR2(20);

COMMENT ON COLUMN CONFIGURAZIONE.CODICEAMMINISTRAZIONE_IPA IS 'Codice amministrazione definita nell''indice delle pubbliche amministrazioni (IPA), al momento utilizzato nelle comunicazioni con Registro imprese per identificare l''amministrazione comunale mittente. Ve definito solamente nel software TT';
COMMENT ON COLUMN CONFIGURAZIONE.CODICE_AOO IS 'Codice Area Omogenea Organizzativa (Con l''acronimo AOO sono identificati gli uffici di protocollo delle Amministrazioni che gestiscono i flussi documentali in entrata e in uscita dall''Amministrazione). Serve per identificare il relativo codice nelle comunicazioni verso enti esterni. Ve definito solamente per ogni software ad eccezione di TT. Al momento viene utilizzato nella comunicazione con registro imprese.';

