ALTER TABLE OGGETTI_METADATI ADD CONSTRAINT FK_OGGETTI_METADATI FOREIGN KEY (IDCOMUNE, CODICEOGGETTO) REFERENCES OGGETTI (IDCOMUNE,CODICEOGGETTO);
COMMENT ON COLUMN OGGETTI_METADATI.CODICEOGGETTO IS 'CHIAVE ESTERNA VERSO LA TABELLA OGGETTI'; 
COMMENT ON COLUMN OGGETTI_METADATI.CHIAVE IS 'NOME O CHIAVE DEL METADATO'; 
COMMENT ON COLUMN OGGETTI_METADATI.VALORE IS 'VALORE DEL METADATO';

CREATE TABLE PROTOCOLLO_MODALITAINVIO(ICOMUNE VARCHAR2(6) NOT NULL, CODICE VARCHAR2(30) NOT NULL, DESCRIZIONE VARCHAR2(300) NOT NULL);
ALTER TABLE PROTOCOLLO_MODALITAINVIO ADD CONSTRAINT PROTOCOLLO_MODALITAINVIO_PK PRIMARY KEY (ICOMUNE,CODICE);
COMMENT ON TABLE PROTOCOLLO_MODALITAINVIO IS 'Contiene i dati relativi alla modalità di invio del protocollo, ad esempio: Per Conoscenza, Forma Diretta, Per Sottocopia....E'' una funzionalità strettamente relativa al protocollo, in particolare questi dati vengono visualizzati sull''interfaccia di protocollazione dentro una dropdownlist di fianco alle amministrazioni / anagrafiche mittente per i protocolli in arrivo, amministrazioni / anagrafiche destinatari per i protocolli in partenza. Se questa tabella non è valorizzata i dropdownlist non saranno visualizzati. La richiesta è stata fatta dal Comune di Trieste.';

